import hashlib
import math

class BloomFilter:
    """A Bloom Filter implementation to test set membership with a configurable probability of false positives.

    The bit array size and number of hash functions are calculated based on the expected number of items
    and the desired false positive rate to optimize space and performance. 
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate size of bit array and number of hash functions
        self.size = self._calculate_bit_array_size()
        self.hash_count = self._calculate_hash_count()

        self.bit_array = [False] * self.size

    def _calculate_bit_array_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return max(1, int(- (self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2)))

    def _calculate_hash_count(self) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((self.size / self.expected_items) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Create a hash of the item using a given seed."""
        hash_object = hashlib.md5((str(seed) + item).encode())
        return int(hash_object.hexdigest(), 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            self.bit_array[index] = True

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            if not self.bit_array[index]:
                return False
        return True

import hashlib
import math

class BloomFilter:
    """A Bloom Filter implementation that tracks membership of items with a specified false positive rate.

    The algorithm utilizes an array of bits and multiple hash functions, which are configurable based on the 
    expected number of items and the desired false positive rate. This design aims for efficient space usage 
    while balancing false positive rates.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal size of the bit array and number of hash functions
        self.size = self._optimal_bit_array_size()
        self.hash_count = self._optimal_hashes_count()

        # Initialize bit array with zeros
        self.bit_array = [0] * (self.size // 32 + 1)

    def _optimal_bit_array_size(self) -> int:
        """Calculate the optimal size of the bit array based on expected number of items and false positive rate."""
        return math.ceil((-self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _optimal_hashes_count(self) -> int:
        """Calculate the optimal number of hash functions required."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash value for the given item and seed."""
        hash_object = hashlib.sha256((str(seed) + item).encode()).hexdigest()
        return int(hash_object, 16) % self.size

    def _set_bit(self, index: int) -> None:
        """Set the bit at the specific index in the bit array."""
        self.bit_array[index // 32] |= (1 << (index % 32))

    def _check_bit(self, index: int) -> bool:
        """Check if the bit at the specific index in the bit array is set."""
        return (self.bit_array[index // 32] & (1 << (index % 32))) != 0

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            self._set_bit(index)

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            if not self._check_bit(index):
                return False
        return True
